cd "C:/tmp/betta-bench/models-oneby-haiku/t1-remap-vanilla-3" && cat > Remap.cs <<'EOF'
using System;
using Grasshopper.Kernel;

namespace BenchPlugin
{
    public class RemapComponent : GH_Component
    {
        public RemapComponent()
            : base("Remap", "Remap", "Remaps a number from a source range to a target range", "Bench", "Math")
        {
        }

        public override Guid ComponentGuid => new Guid("GUID_PLACEHOLDER");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddNumberParameter("Value", "V", "Number to remap", GH_ParamAccess.item, 0.0);
            pManager.AddNumberParameter("Source Min", "S0", "Lower bound of the source range", GH_ParamAccess.item, 0.0);
            pManager.AddNumberParameter("Source Max", "S1", "Upper bound of the source range", GH_ParamAccess.item, 1.0);
            pManager.AddNumberParameter("Target Min", "T0", "Lower bound of the target range", GH_ParamAccess.item, 0.0);
            pManager.AddNumberParameter("Target Max", "T1", "Upper bound of the target range", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Result", "R", "Value mapped into the target range", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            double value = 0, sourceMin = 0, sourceMax = 1, targetMin = 0, targetMax = 1;
            if (!DA.GetData(0, ref value)) return;
            if (!DA.GetData(1, ref sourceMin)) return;
            if (!DA.GetData(2, ref sourceMax)) return;
            if (!DA.GetData(3, ref targetMin)) return;
            if (!DA.GetData(4, ref targetMax)) return;

            double sourceSpan = sourceMax - sourceMin;
            double t = sourceSpan == 0.0 ? 0.0 : (value - sourceMin) / sourceSpan;
            DA.SetData(0, targetMin + t * (targetMax - targetMin));
        }
    }
}
EOF
guid=$(powershell.exe -NoProfile -Command "[guid]::NewGuid().ToString()" | tr -d '\r')
sed -i "s/GUID_PLACEHOLDER/$guid/" Remap.cs && grep -n "new Guid" Remap.cs && grep -rn "ComponentGuid\|new Guid" AddComponent.cs BenchPluginInfo.cs
